CREATE POLICY "Users can view their own v3 conversations" ON public.conversations_v3 FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "Users can insert their own v3 conversations" ON public.conversations_v3 FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can update their own v3 conversations" ON public.conversations_v3 FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can delete their own v3 conversations" ON public.conversations_v3 FOR DELETE TO authenticated USING (auth.uid() = user_id);